-- Cascading public school location filters: County -> Sub-county -> Ward.
-- Counties are seeded nationally; Nakuru sub-counties/wards are the first verified county hierarchy.

create table if not exists public.kenya_administrative_areas (
  county text not null,
  sub_county text,
  ward text,
  source_name text,
  source_url text,
  verified_at timestamptz not null default now(),
  constraint kenya_administrative_areas_shape_check check (ward is null or sub_county is not null)
);

create unique index if not exists kenya_administrative_areas_unique_idx
on public.kenya_administrative_areas (lower(county), lower(coalesce(sub_county,'')), lower(coalesce(ward,'')));

alter table public.kenya_administrative_areas enable row level security;
revoke all on table public.kenya_administrative_areas from public, anon, authenticated;
-- access: service-only public.kenya_administrative_areas
-- authorization-test: public.kenya_administrative_areas

