create or replace function public.schools_location_options_public_v1(p_county text default null,p_sub_county text default null)
returns table(option_type text,value text) language sql stable security definer set search_path=public,pg_temp as $$
with counties as (select distinct county value from public.kenya_administrative_areas where county is not null union select distinct county::text from public.schools where deleted_at is null and status='active' and county is not null and trim(county)<>''),
subs as (select distinct sub_county value from public.kenya_administrative_areas where sub_county is not null and (p_county is null or lower(county)=lower(trim(p_county))) union select distinct sub_county::text from public.schools where deleted_at is null and status='active' and sub_county is not null and trim(sub_county)<>'' and (p_county is null or lower(county)=lower(trim(p_county)))),
wards as (select distinct ward value from public.kenya_administrative_areas where ward is not null and (p_county is null or lower(county)=lower(trim(p_county))) and (p_sub_county is null or lower(sub_county)=lower(trim(p_sub_county))) union select distinct ward::text from public.schools where deleted_at is null and status='active' and ward is not null and trim(ward)<>'' and (p_county is null or lower(county)=lower(trim(p_county))) and (p_sub_county is null or lower(sub_county)=lower(trim(p_sub_county))))
select 'county',value from counties union all select 'sub_county',value from subs where p_county is not null and trim(p_county)<>'' union all select 'ward',value from wards where p_county is not null and trim(p_county)<>'' and p_sub_county is not null and trim(p_sub_county)<>'' order by 1,2;
$$;
revoke all on function public.schools_location_options_public_v1(text,text) from public; grant execute on function public.schools_location_options_public_v1(text,text) to anon,authenticated;

create or replace function public.schools_search_public_v2(p_query text default null,p_county text default null,p_sub_county text default null,p_ward text default null,p_school_category text default null,p_ownership_type text default null,p_gender_type text default null,p_accommodation_type text default null,p_limit integer default 50)
returns table(school_id uuid,school_name text,county text,sub_county text,ward text,school_category text,ownership_type text,gender_type text,accommodation_type text,cluster text,knec_code text) language sql stable security definer set search_path=public,pg_temp as $$ select s.id,s.name::text,s.county::text,s.sub_county::text,s.ward::text,s.school_category::text,s.ownership_type,s.gender_type,s.accommodation_type,s.cluster,s.knec_code::text from public.schools s where s.deleted_at is null and s.status='active' and (p_query is null or trim(p_query)='' or lower(s.name) like '%'||lower(trim(p_query))||'%') and (p_county is null or trim(p_county)='' or lower(coalesce(s.county,''))=lower(trim(p_county))) and (p_sub_county is null or trim(p_sub_county)='' or lower(coalesce(s.sub_county,''))=lower(trim(p_sub_county))) and (p_ward is null or trim(p_ward)='' or lower(coalesce(s.ward,''))=lower(trim(p_ward))) and (p_school_category is null or trim(p_school_category)='' or lower(coalesce(s.school_category::text,''))=lower(trim(p_school_category))) and (p_ownership_type is null or trim(p_ownership_type)='' or lower(coalesce(s.ownership_type,''))=lower(trim(p_ownership_type))) and (p_gender_type is null or trim(p_gender_type)='' or lower(coalesce(s.gender_type,''))=lower(trim(p_gender_type))) and (p_accommodation_type is null or trim(p_accommodation_type)='' or lower(coalesce(s.accommodation_type,''))=lower(trim(p_accommodation_type))) order by case when p_query is not null and lower(s.name)=lower(trim(p_query)) then 0 else 1 end,s.name asc limit least(greatest(coalesce(p_limit,50),1),100); $$;
revoke all on function public.schools_search_public_v2(text,text,text,text,text,text,text,text,integer) from public; grant execute on function public.schools_search_public_v2(text,text,text,text,text,text,text,text,integer) to anon,authenticated;

create or replace function public.schools_search_community_pending_v2(p_query text default null,p_county text default null,p_sub_county text default null,p_ward text default null,p_level text default null,p_limit integer default 25)
returns table(request_id uuid,school_name text,county text,sub_county text,ward text,school_level text,submitted_at timestamptz) language sql stable security definer set search_path=public,pg_temp as $$ select r.id,r.name,r.county,r.sub_county,r.ward,r.level,r.created_at from public.school_discovery_requests r where r.status='pending' and r.request_type='missing_or_new' and r.target_school_id is null and (p_query is null or trim(p_query)='' or lower(r.name) like '%'||lower(trim(p_query))||'%') and (p_county is null or trim(p_county)='' or lower(coalesce(r.county,''))=lower(trim(p_county))) and (p_sub_county is null or trim(p_sub_county)='' or lower(coalesce(r.sub_county,''))=lower(trim(p_sub_county))) and (p_ward is null or trim(p_ward)='' or lower(coalesce(r.ward,''))=lower(trim(p_ward))) and (p_level is null or trim(p_level)='' or lower(coalesce(r.level,''))=lower(trim(p_level))) order by r.created_at desc limit least(greatest(coalesce(p_limit,25),1),50); $$;
revoke all on function public.schools_search_community_pending_v2(text,text,text,text,text,integer) from public; grant execute on function public.schools_search_community_pending_v2(text,text,text,text,text,integer) to anon,authenticated;
